import sys
from collections import defaultdict, deque

def find_routes(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start, end):
        queue = deque([(start, [start])])
        visited = set()
        while queue:
            node, path = queue.popleft()
            if node == end:
                return path
            if node in visited:
                continue
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited and (node, neighbor) not in visited_edges and (neighbor, node) not in visited_edges:
                    visited_edges.add((node, neighbor))
                    visited_edges.add((neighbor, node))
                    queue.append((neighbor, path + [neighbor]))
        return None

    visited_edges = set()
    routes = []
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if len(routes) == 3:
                break
            path1 = bfs(i, j)
            if path1:
                routes.append(path1)
                visited_edges.clear()
                path2 = bfs(i, j)
                if path2:
                    routes.append(path2)
                    visited_edges.clear()
                    path3 = bfs(i, j)
                    if path3:
                        routes.append(path3)
                        break
    if len(routes) == 3:
        return "YES\n" + "\n".join(f"{len(route)} {' '.join(map(str, route))}" for route in routes)
    return "NO"

input = sys.stdin.read().split()
n = int(input[0])
m = int(input[1])
edges = [(int(input[2 + 2 * i]), int(input[3 + 2 * i])) for i in range(m)]
print(find_routes(n, edges))
